  1941	export async function getManagedHostRunStatus(args: {
  1942	  root: string;
  1943	  runId: string;
  1944	  afterGeneration?: number;
  1945	  waitMs?: number;
  1946	  /** Internal handler-smoke seam; production omits this and retains the 30s cap. */
  1947	  maxWaitMs?: number;
  1948	  /** Internal process-smoke clock seam; production always uses Date.now. */
  1949	  now?: () => number;
  1950	  /** Process-boundary seam used by executable cleanup-fact tests; production uses OS process groups. */
  1951	  processGroupOps?: ManagedHostRunProcessGroupOps;
  1952	}): Promise<ManagedHostRunStatusResult> {
  1953	  const paths = pathsFor(args.root, args.runId);
  1954	  if (!existsSync(paths.spec)) throw new Error(`managed host run not found: ${args.runId}`);
  1955	  const waitMs = Math.min(
  1956	    boundedManagedHostRunStatusWaitMs(args.waitMs),
  1957	    boundedManagedHostRunStatusWaitMs(args.maxWaitMs ?? MANAGED_HOST_RUN_STATUS_WAIT_MAX_MS),
  1958	  );
  1959	  let run = projectionFor(paths);
  1960	  const baseline = typeof args.afterGeneration === 'number' ? args.afterGeneration : run.generation;
  1961	  const now = args.now ?? Date.now;
  1962	  const deadline = now() + waitMs;
  1963	  while (true) {
  1964	    await reconcileManagedHostRun(paths, now(), args.processGroupOps);
  1965	    run = projectionFor(paths);
  1966	    const changed = run.generation !== baseline || run.terminal !== null;
  1967	    if (changed || now() >= deadline || waitMs === 0) {
  1968	      return {
  1969	        schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
  1970	        changed,
  1971	        run,
  1972	        receipt: run.terminal ? managedHostRunReceipt(args.root, args.runId) : null,
  1973	      };
  1974	    }
  1975	    await sleep(Math.min(50, Math.max(1, deadline - now())));
  1976	  }
  1977	}
